# First, let me identify connected components for each non-background, non-anchor color
from collections import deque, defaultdict

def find_connected_components(grid, rows, cols):
    """Find all connected components of non-4, non-5 colors"""
    components = defaultdict(list)
    visited = set()

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color in [4, 5]:  # Skip background and anchor
                continue
            if (r, c) in visited:
                continue

            # BFS/DFS to find connected component
            component = []
            queue = deque([(r, c)])
            visited.add((r, c))

            while queue:
                cr, cc = queue.popleft()
                component.append((cr, cc))

                for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

            components[color].append(component)

    return components

def get_block_shape(component):
    """Get the bounding box of a component and check if it's rectangular"""
    rows_of_comp = set(p[0] for p in component)
    cols_of_comp = set(p[1] for p in component)
    return (max(rows_of_comp), min(rows_of_comp), max(cols_of_comp), min(cols_of_comp))

