import numpy as np

print("Available test input:", test_input.shape if isinstance(test_input, np.ndarray) else "not an array")

# Transform test_input: Apply all rules learned from D1-D5
# D1: 1s in rows 1-2 below rows with 2s become 2s
# D2: 2s in rows 1-2 adjacent to 0s become 0s  
# D3: 8s in col 0 become 5s if row has 5
# D4: 1s in rows 1-2 below rows with 2s become 2s (same as D1)
# D5: 3s left of 0 in same row become 0

def apply_all_rules(grid):
    """Apply all transformation rules learned from D1-D5"""
    result = grid.copy().astype(int)

    # Rule D1/D4: 1s in rows 1-2 below rows with 2s become 2s
    for r in range(1, min(3, len(grid))):  # rows 1 and 2
        for c in range(len(grid[0])):
            if grid[r][c] == 1:
                # Check if any row above has 2
                has_2_above = any(np.any(grid[:r] == 2, axis=1))
                if has_2_above:
                    result[r][c] = 2

    # Rule D2: 2s in rows 1-2 adjacent to 0s become 0s
    for r in range(1, min(3, len(grid))):
        for c in range(len(grid[0])):
            if grid[r][c] == 2:
                # Check 4 neighbors for 0
                neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
                if any(0 in (grid[nr][nc] if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) else []) for nr, nc in neighbors):
                    result[r][c] = 0

    # Rule D3/D5 extension: 8s in col 0 become 5s if row has 5
    for r in range(len(grid)):
        if grid[r][0] == 8:
            if 5 in grid[r]:
                result[r][0] = 5

    # Rule D5: 3s left of 0 in same row become 0
    for r in range(len(grid)):
        zero_positions = [c for c in range(len(grid[0])) if grid[r][c] == 0]
        if zero_positions:
            for c in range(len(grid[0])):
                if grid[r][c] == 3:
                    # Check if any 0 is to the right of this 3
                    right_zeros = [z for z in zero_positions if z > c]
                    if right_zeros:
                        result[r][c] = 0

    return result

